<template><view class="bottom-bar"><view v-for="i in items" :key="i.name" class="bottom-item" :class="{on:active===i.name}" @click="go(i)"><view class="bottom-icon">{{i.icon}}</view>{{i.name}}</view></view></template>
<script setup>
defineProps({active:{type:String,default:'首页'}})
const items=[{name:'首页',icon:'⌂',url:'/pages/index/index'},{name:'题库',icon:'✎'},{name:'资料',icon:'▤'},{name:'旅行',icon:'⌁',url:'/pages/travel/index'},{name:'我的',icon:'◉',url:'/pages/mine/index'}]
const go=i=>i.url?uni.reLaunch({url:i.url}):uni.showToast({title:`${i.name}模块演示入口`,icon:'none'})
</script>
